using System.Xml.Linq;

namespace Pubwiz.Core.Profiles;

/// <summary>
/// Imports .publishsettings files (downloaded from the Azure portal or generated by IIS Web Deploy)
/// the same way Visual Studio's "Import Profile" does.
/// </summary>
/// <remarks>
/// File format:
/// <code>
/// &lt;publishData&gt;
///   &lt;publishProfile profileName="site - Web Deploy" publishMethod="MSDeploy" publishUrl="site.scm.azurewebsites.net:443"
///                   msdeploySite="site" userName="$site" userPWD="..." destinationAppUrl="https://site.azurewebsites.net" /&gt;
///   &lt;publishProfile profileName="site - FTP" publishMethod="FTP" publishUrl="ftps://.../site/wwwroot" ftpPassiveMode="True" ... /&gt;
/// &lt;/publishData&gt;
/// </code>
/// </remarks>
public static class PublishSettingsImporter
{
    public const string FileExtension = ".publishsettings";

    /// <summary>
    /// Reads all entries of a .publishsettings file. Entries with a publish method Pubwiz doesn't support are skipped.
    /// </summary>
    public static IReadOnlyList<PublishSettingsEntry> Read(string filePath) => Parse(XDocument.Load(filePath));

    internal static IReadOnlyList<PublishSettingsEntry> Parse(XDocument document)
    {
        var entries = document.Root?.Elements("publishProfile") ?? [];

        return entries
            .Select(ParseEntry)
            .Where(entry => entry.Method is PublishMethod.MSDeploy or PublishMethod.FTP or PublishMethod.ZipDeploy)
            .ToList();
    }

    /// <summary>
    /// Converts an entry into a .pubxml profile with the properties Visual Studio would write.
    /// </summary>
    public static ImportedProfile ToProfile(PublishSettingsEntry entry)
    {
        var profile = new PublishProfile(PublishProfileStore.ToValidName(entry.ProfileName));

        profile[ProfileProperties.WebPublishMethod] = entry.Method.ToString();
        if (entry.IsAzure)
        {
            profile[ProfileProperties.PublishProvider] = ProfileProperties.AzureWebSiteProvider;
        }

        profile[ProfileProperties.LastUsedBuildConfiguration] = "Release";
        profile[ProfileProperties.LastUsedPlatform] = "Any CPU";

        if (entry.DestinationAppUrl is not null)
        {
            profile[ProfileProperties.SiteUrlToLaunchAfterPublish] = entry.DestinationAppUrl;
            profile[ProfileProperties.LaunchSiteAfterPublish] = "true";
        }

        switch (entry.Method)
        {
            case PublishMethod.MSDeploy:
                profile[ProfileProperties.MSDeployServiceURL] = entry.PublishUrl;
                profile[ProfileProperties.DeployIisAppPath] = entry.SiteName;
                profile[ProfileProperties.MSDeployPublishMethod] = "WMSVC";
                profile[ProfileProperties.EnableMSDeployBackup] = entry.IsAzure ? "true" : null;
                profile[ProfileProperties.SkipExtraFilesOnServer] = "false";
                break;

            case PublishMethod.ZipDeploy:
                profile[ProfileProperties.PublishUrl] = ToHttpsUrl(entry.PublishUrl);
                break;

            case PublishMethod.FTP:
                profile[ProfileProperties.PublishUrl] = entry.PublishUrl;
                profile[ProfileProperties.FtpPassiveMode] = entry.FtpPassiveMode ? "true" : "false";
                break;
        }

        profile[ProfileProperties.UserName] = entry.UserName;
        return new ImportedProfile(profile, entry.Password);
    }

    private static PublishSettingsEntry ParseEntry(XElement element)
    {
        return new PublishSettingsEntry(
            ProfileName: Attribute(element, "profileName") ?? "Imported",
            Method: PublishMethodParser.Parse(Attribute(element, "publishMethod")),
            PublishUrl: Attribute(element, "publishUrl") ?? string.Empty,
            SiteName: Attribute(element, "msdeploySite"),
            UserName: Attribute(element, "userName"),
            Password: Attribute(element, "userPWD"),
            DestinationAppUrl: Attribute(element, "destinationAppUrl"),
            FtpPassiveMode: !string.Equals(Attribute(element, "ftpPassiveMode"), "false", StringComparison.OrdinalIgnoreCase));
    }

    private static string? Attribute(XElement element, string name)
    {
        var value = element.Attribute(name)?.Value;
        return string.IsNullOrWhiteSpace(value) ? null : value;
    }

    /// <summary>
    /// Zip deploy entries hold a bare host (<c>site.scm.azurewebsites.net:443</c>); the Web SDK expects an https URL.
    /// </summary>
    private static string ToHttpsUrl(string publishUrl)
    {
        if (publishUrl.StartsWith("http", StringComparison.OrdinalIgnoreCase))
        {
            return publishUrl;
        }

        var host = publishUrl.EndsWith(":443", StringComparison.Ordinal) ? publishUrl[..^4] : publishUrl;
        return $"https://{host}/";
    }
}
